import{_ as a}from"./chunks/schedule.ZDSBYxh8.js";import{_ as o,o as t,c as r,a3 as s}from"./chunks/framework.CchDE9cb.js";const w=JSON.parse('{"title":"The schedule","description":"How to read the grid — rows, columns, colours and states — that every other CapacityLens screen feeds into.","frontmatter":{"title":"The schedule","description":"How to read the grid — rows, columns, colours and states — that every other CapacityLens screen feeds into."},"headers":[],"relativePath":"guide/the-schedule.md","filePath":"guide/the-schedule.md","lastUpdated":null}'),n={name:"guide/the-schedule.md"};function i(l,e,h,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="the-schedule" tabindex="-1">The schedule <a class="header-anchor" href="#the-schedule" aria-label="Permalink to &quot;The schedule&quot;">​</a></h1><p>The schedule is the one screen CapacityLens is built around: every person, every allocation and every day of time off, all on a single zoomable grid. This page explains what you&#39;re looking at so you can read <a href="/capacitylens/reference/glossary">utilisation</a> at a glance instead of clicking around to check.</p><p><img src="'+a+'" alt="The Schedule view with people grouped by discipline, allocation bars, utilisation percentages and a holiday block"></p><h2 id="rows-your-people" tabindex="-1">Rows: your people <a class="header-anchor" href="#rows-your-people" aria-label="Permalink to &quot;Rows: your people&quot;">​</a></h2><p>Each row is one <a href="/capacitylens/reference/glossary">person</a> — a real teammate, a freelancer, or a <a href="/capacitylens/reference/glossary">placeholder</a> for a role you haven&#39;t filled yet. Rows are grouped under a <a href="/capacitylens/reference/glossary">discipline</a> heading (Design, Development, and so on) when your company uses disciplines, which is the default. A group header can be collapsed to <code>{count} hidden</code>, and shows an average utilisation figure for everyone in it when that figure is turned on in Settings.</p><p>Each row starts with an avatar and name, with the person&#39;s role shown underneath. A placeholder row is labelled with the word &quot;Placeholder&quot; instead of a name, and has a faint diagonal hatch on its header so it reads as unfilled at a glance.</p><h2 id="columns-the-visible-weeks" tabindex="-1">Columns: the visible weeks <a class="header-anchor" href="#columns-the-visible-weeks" aria-label="Permalink to &quot;Columns: the visible weeks&quot;">​</a></h2><p>Columns are days, grouped into a zoomable range of one, two, four, six or eight weeks at a time — the segmented control in the toolbar switches between them (<code>1w</code>, <code>2w</code>, and so on). Use <strong>Prev</strong> and <strong>Next</strong> to pan a week at a time, <strong>Today</strong> to jump back to the current week, or the date field to jump straight to a specific day.</p><p>Weekend columns get a faint tint when you&#39;re zoomed in close enough to see individual days clearly.</p><h2 id="allocation-bars" tabindex="-1">Allocation bars <a class="header-anchor" href="#allocation-bars" aria-label="Permalink to &quot;Allocation bars&quot;">​</a></h2><p>An <a href="/capacitylens/reference/glossary">allocation</a> — a person booked on a project for a date range — shows as a coloured bar spanning the days it covers, coloured by project or <a href="/capacitylens/reference/glossary">activity</a>. Three statuses are visible directly on the bar:</p><ul><li><strong>Confirmed</strong> — a plain, solid bar. This is the default when you create one.</li><li><strong>Tentative</strong> — the same bar with a dashed border and a light diagonal hatch, so work that isn&#39;t locked in yet still stands out from confirmed work.</li><li><strong>Completed</strong> — the bar&#39;s label gets a checkmark prefix.</li></ul><p>Depending on your device preferences, a bar&#39;s label can also show the client and project name ahead of the activity name, plus the hours booked per day. Companies that plan in Blocks don&#39;t book hours at all — see <a href="/capacitylens/guide/projects-and-allocations">Projects and allocations</a> for how the different scheduling modes work.</p><h2 id="reading-overwork" tabindex="-1">Reading overwork <a class="header-anchor" href="#reading-overwork" aria-label="Permalink to &quot;Reading overwork&quot;">​</a></h2><p>CapacityLens never makes you run a report to find out who&#39;s overbooked:</p><ul><li>A <strong>utilisation percentage</strong> sits beside each row, and can also be shown as a company-wide total and a per-discipline average — all three are switches in <a href="/capacitylens/guide/settings">Settings</a>. A person&#39;s own percentage turns bold and red as soon as they&#39;re booked over capacity within the next 14 days, regardless of what&#39;s currently zoomed into view.</li><li>Any day where a person is booked for more than they&#39;re available gets a red band under the bars for that day, so the exact day that tips someone over capacity is obvious without doing the maths yourself.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The utilisation percentage itself is worked out over whatever date range is currently visible — one, two, four, six or eight weeks. Zoom out to two weeks and a person&#39;s percentage will usually drop, because it&#39;s now averaged over more days; zoom back to one week and it rises again. That&#39;s expected, not a bug: the percentage always answers &quot;how booked is this person over the weeks I&#39;m looking at right now?&quot; The red over-capacity warning is separate and doesn&#39;t move when you zoom — it always looks at the fixed next 14 days, so someone can show red even while you&#39;re viewing a wider, less-full-looking range.</p></div><h2 id="time-off-on-the-same-canvas" tabindex="-1">Time off on the same canvas <a class="header-anchor" href="#time-off-on-the-same-canvas" aria-label="Permalink to &quot;Time off on the same canvas&quot;">​</a></h2><p><a href="/capacitylens/guide/time-off">Time off</a> — holiday, sick leave or unpaid leave — is drawn on the same grid as work, as a hatched block with no project colour, so a person&#39;s real availability is always visible in one place rather than hidden in a separate calendar.</p><h2 id="filtering-and-searching" tabindex="-1">Filtering and searching <a class="header-anchor" href="#filtering-and-searching" aria-label="Permalink to &quot;Filtering and searching&quot;">​</a></h2><p>The toolbar above the grid lets you narrow what&#39;s shown: search people by name, filter by discipline, client, project or activity, hide tentative work, or show only people with no work booked against your current filter (useful when you&#39;re trying to find someone free to staff a project). A <strong>Clear</strong> button appears whenever a filter is active.</p><p>Every change on the schedule — dragging, resizing, deleting an allocation — can be undone and redone from the toolbar, or with Ctrl/Cmd+Z, if you have edit access.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Rows, colours and percentages update live as you drag. There&#39;s nothing to refresh and nothing to recalculate — what you see is always current.</p></div><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p><a href="/capacitylens/guide/people-and-placeholders">People and placeholders</a> covers who can appear on the schedule, and <a href="/capacitylens/guide/projects-and-allocations">Projects and allocations</a> covers how the bars themselves get created.</p>',25)])])}const f=o(n,[["render",i]]);export{w as __pageData,f as default};
